// @generated by:gauntlet run:godseye-local-infrastructure
import { randomUUID } from "node:crypto";
import { availableParallelism, totalmem } from "node:os";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { LocalSystemCollector } from "../packages/core/src/infra-collector.js";
import { InfrastructureEngine } from "../packages/core/src/infrastructure.js";
import {
  desiredInventory,
  type InfrastructureFixture,
  infrastructureFixture,
} from "./infra-helpers.js";

describe("versioned infrastructure truth and qualification", () => {
  let fixture: InfrastructureFixture;
  beforeEach(async () => {
    fixture = await infrastructureFixture();
  });
  afterEach(async () => {
    await fixture.store.close();
  });

  it("T-AC-19 T25 reports native development-controller observations without inventing a server or PID limit", async () => {
    const observation = await new LocalSystemCollector().collect();

    expect(observation.target).toBe("development-controller");
    expect(observation.hostCapacity).toBeNull();
    expect(observation.capacity.cpuMilliCores).toBe(availableParallelism() * 1000);
    expect(observation.capacity.memoryMiB).toBe(Math.floor(totalmem() / 1_048_576));
    expect(observation.capacity.pids).toBeNull();
    expect(Object.values(observation.qualification).every((qualified) => !qualified)).toBe(true);
    expect(observation.filesystem?.availableGiB).toBe(observation.capacity.storageGiB);
    expect((observation.filesystem?.totalGiB ?? 0) >= observation.capacity.storageGiB).toBe(true);
  });

  it("T-AC-19 T34 cannot turn a desired declaration into observed or qualified infrastructure", async () => {
    const unobserved = new InfrastructureEngine(fixture.store, { now: fixture.clock.now });
    const before = await unobserved.overview(fixture.freshOwner());
    const desired = desiredInventory();
    desired.expectedRevision = before.revision;

    const result = await unobserved.declareInventory(fixture.freshOwner(), desired, randomUUID());

    expect(result.observation).toEqual(before.observation);
    expect(result.observationRevision).toBe(before.observationRevision);
    expect(result.executionAvailable).toBe(false);
    await expect(
      unobserved.declareInventory(
        fixture.freshOwner(),
        { ...desired, qualified: true } as typeof desired,
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 422 });
  });

  it("T-AC-19 T37 replays inventory mutations before revision guards and refuses changed content under one key", async () => {
    const desired = desiredInventory();
    desired.expectedRevision = 1;
    const key = randomUUID();

    const first = await fixture.infrastructure.declareInventory(fixture.freshOwner(), desired, key);
    const replay = await fixture.infrastructure.declareInventory(
      fixture.freshOwner(),
      desired,
      key,
    );

    expect(replay).toEqual(first);
    await expect(
      fixture.infrastructure.declareInventory(
        fixture.freshOwner(),
        { ...desired, host: { ...desired.host, name: "Changed topology" } },
        key,
      ),
    ).rejects.toMatchObject({ status: 409 });
    await expect(
      fixture.infrastructure.declareInventory(fixture.freshOwner(), desired, randomUUID()),
    ).rejects.toMatchObject({ status: 409 });
  });

  it("T-AC-19 T22 rejects service administration and owner mutations after passkey freshness expires", async () => {
    const service = {
      id: "project-service",
      kind: "service" as const,
      projectIds: [fixture.project.id],
    };
    await expect(fixture.infrastructure.overview(service)).rejects.toMatchObject({ status: 403 });
    await expect(
      fixture.infrastructure.refreshInventory(service, { expectedRevision: 1 }, randomUUID()),
    ).rejects.toMatchObject({ status: 403 });
    const actor = fixture.freshOwner();
    fixture.clock.advance(300_001);

    await expect(
      fixture.infrastructure.declareInventory(
        actor,
        { ...desiredInventory(), expectedRevision: 1 },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 403 });
    expect((await fixture.infrastructure.overview(fixture.freshOwner())).revision).toBe(1);
  });

  it("T-AC-19 T25 shows stale observations and blocks admission without creating provider resources", async () => {
    const preparation = await fixture.prepare();
    fixture.clock.advance(300_001);
    const overview = await fixture.infrastructure.overview(fixture.freshOwner());

    expect(overview.observationState).toBe("stale");
    expect(overview.executionAvailable).toBe(false);
    await expect(
      fixture.infrastructure.admit(
        fixture.freshOwner(),
        { preparationId: preparation.id, expectedHash: preparation.hash },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 503 });
    expect(fixture.provider.effects).toHaveLength(0);
    expect((await fixture.infrastructure.overview(fixture.freshOwner())).allocations).toHaveLength(
      0,
    );
  });

  it("T-AC-25 T04 refuses every unsupported enforcement capability rather than substituting native execution", async () => {
    for (const capability of Object.keys(
      fixture.collector.observation.qualification,
    ) as (keyof typeof fixture.collector.observation.qualification)[]) {
      const prior = await fixture.infrastructure.overview(fixture.freshOwner());
      fixture.collector.observation.qualification[capability] = false;
      await fixture.infrastructure.refreshInventory(
        fixture.freshOwner(),
        { expectedRevision: prior.observationRevision },
        randomUUID(),
      );
      const preparation = await fixture.prepare();

      await expect(
        fixture.infrastructure.admit(
          fixture.freshOwner(),
          { preparationId: preparation.id, expectedHash: preparation.hash },
          randomUUID(),
        ),
        capability,
      ).rejects.toMatchObject({ status: 503 });
      fixture.collector.observation.qualification[capability] = true;
    }
    expect(fixture.provider.effects).toHaveLength(0);
    expect((await fixture.infrastructure.overview(fixture.freshOwner())).allocations).toHaveLength(
      0,
    );
  });

  it("T-AC-19 T34 refuses observation and desired revisions that changed after immutable preparation", async () => {
    const preparation = await fixture.prepare();
    await fixture.infrastructure.refreshInventory(
      fixture.freshOwner(),
      { expectedRevision: 1 },
      randomUUID(),
    );

    await expect(
      fixture.infrastructure.admit(
        fixture.freshOwner(),
        { preparationId: preparation.id, expectedHash: preparation.hash },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 409 });
    expect(fixture.provider.effects).toHaveLength(0);
  });

  it("T-AC-21 T02 enforces one professional VM and at most two justified public IPv4 addresses", async () => {
    const desired = { ...desiredInventory(), expectedRevision: 1 };
    await expect(
      fixture.infrastructure.declareInventory(
        fixture.freshOwner(),
        { ...desired, publicIpv4Count: 2 },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 422 });
    await expect(
      fixture.infrastructure.declareInventory(
        fixture.freshOwner(),
        { ...desired, publicIpv4Count: 3 } as typeof desired,
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 422 });
    await expect(
      fixture.infrastructure.declareInventory(
        fixture.freshOwner(),
        { ...desired, guests: [desired.guests[0], desired.guests[0]] } as typeof desired,
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 422 });
    const accepted = await fixture.infrastructure.declareInventory(
      fixture.freshOwner(),
      {
        ...desired,
        publicIpv4Count: 2,
        secondIpv4Justification: "A demonstrated fixed-port collision requires the second address",
      },
      randomUUID(),
    );
    expect(accepted.desired?.publicIpv4Count).toBe(2);
    expect(fixture.provider.effects).toHaveLength(0);
  });
});
